import {defaultProfile,normalizeProfile,rankJobs,SKILL_OPTIONS} from './matching.js';
import {ROLE_FAMILIES,unique,locationText,salaryText} from './core.js';

const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roles=[
 {name:'AI Applications',icon:'↗',verb:'Build things people use',title:'AI application engineer',description:'Turn models into useful products: a search tool, an assistant, or a document workflow.',day:'Connect a model to an application, test its answers, and improve the user experience.',project:'Build a small question-answering tool over public documents. Show where its answers fail, not just a working demo.'},
 {name:'ML Engineering',icon:'⌁',verb:'Make models work in practice',title:'Machine learning engineer',description:'Train, evaluate, and deliver models that solve a concrete problem.',day:'Prepare data, compare model experiments, and work with software engineers to ship a reliable model.',project:'Train a baseline on a public dataset, compare one improvement, and explain errors on held-out examples.'},
 {name:'Research',icon:'✳',verb:'Ask questions and run experiments',title:'Research scientist / engineer',description:'Investigate how models work and test ideas for improving them.',day:'Read papers, design experiments, and check whether an improvement holds up against a baseline.',project:'Reproduce a small published experiment. Change one factor and report both successful and unsuccessful results.'},
 {name:'ML Infrastructure',icon:'▦',verb:'Make the systems run better',title:'ML infrastructure engineer',description:'Build the tools and systems that train and serve models reliably.',day:'Debug performance, automate experiments, and improve model training or serving infrastructure.',project:'Serve a small model and measure latency and throughput under a few workloads. Explain a performance trade-off.'},
 {name:'Applied Data Science',icon:'◈',verb:'Find patterns that guide decisions',title:'Applied data scientist',description:'Use data, statistics, and predictive models to answer a business question.',day:'Analyze a dataset, test an assumption, and translate the result into a decision someone can make.',project:'Use a public dataset to answer one decision question. Compare a simple model with a baseline and document uncertainty.'}
];
const states='AL AK AZ AR CA CO CT DE DC FL GA HI ID IL IN IA KS KY LA ME MD MA MI MN MS MO MT NE NV NH NJ NM NY NC ND OH OK OR PA RI SC SD TN TX UT VT VA WA WV WI WY'.split(' ');
const storageKey='compass-profile-v2';
const statusNames={aligned:'Stated basics align',confirm:'Check requirements',gap:'A stated condition differs'};
const sourceNames={explicit:'Explicit new grad','zero-experience':'Zero-experience pathway','early-career':'0–2 year pathway',unclear:'Graduate eligibility unclear'};
let profile=defaultProfile(),stage='welcome',step=0,remember=false,allDirections=false,tab='all',limit=6,scope='all',scenarioSkill='',scenarioWide=false,container,context;
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved?.profile){profile=normalizeProfile(saved.profile);remember=true;stage='results';}}catch{}
function persist(){try{if(remember)localStorage.setItem(storageKey,JSON.stringify({profile}));else localStorage.removeItem(storageKey);}catch{context?.toast('The browser could not remember your preferences.');}}
function tag(text,cls=''){return `<span class="tag ${cls}">${escape(text)}</span>`;}
function field(key,label,values,help=''){return `<label class="journey-field"><span>${label}</span><select data-profile="${key}">${values.map(([v,l])=>`<option value="${escape(v)}" ${String(profile[key])===String(v)?'selected':''}>${escape(l)}</option>`).join('')}</select>${help?`<small>${help}</small>`:''}</label>`;}
function chips(key,values){return `<div class="choice-chips">${values.map(v=>`<button class="choice-chip ${profile[key].includes(v)?'selected':''}" data-pick="${key}" data-value="${escape(v)}" aria-pressed="${profile[key].includes(v)}">${escape(v)} ${profile[key].includes(v)?'✓':'+'}</button>`).join('')}</div>`;}
function pool(){return context.jobs.filter(j=>scope==='all'||scope==='graduate'&&['explicit','zero-experience'].includes(j.newgradStatus)||scope==='early'&&j.newgradStatus!=='unclear');}
function welcome(){const jobs=context.jobs;return `<section class="journey-hero"><div class="hero-copy"><p class="eyebrow">YOUR FIRST ROLE IN AI STARTS HERE</p><h1>You don’t need to know<br>your job title <em>yet.</em></h1><p>Start with what you enjoy and what you’ve tried.<br>Find your direction, understand the requirements,<br class="desktop-break"> and build a shortlist that makes sense for you.</p><div class="hero-actions"><button class="button primary large" data-journey="start">Find my starting point <span>↗</span></button><button class="text-button" data-view="explore">Browse all roles →</button></div><p class="privacy-line">About 2 minutes · No account or résumé · Stays in this browser</p></div><div class="path-preview" aria-label="A preview of your personalized exploration"><div class="path-top"><span class="mini-dot"></span> A DIRECTION, NOT A DESTINATION</div><div class="path-node you"><span>01 / YOUR STARTING POINT</span><strong>What do you like doing?</strong><div>Build products · Run experiments · Find patterns</div></div><div class="path-connector"></div><div class="path-branch"><div class="path-node small"><span>02 / UNDERSTAND</span><strong>Learn the roles</strong><p>Real work, plain language.</p></div><div class="path-node small"><span>03 / EXPLORE</span><strong>See your options</strong><p>Evidence behind every match.</p></div></div><div class="path-connector"></div><div class="path-node destination"><span class="star">✳</span><div><strong>Your next useful step</strong><p>A shortlist. A question to ask. A project to try.</p></div></div></div></section><div class="journey-proof"><strong>${jobs.length} public listings</strong><span>${unique(jobs.map(j=>j.company)).length} employers</span><span>${unique(jobs.flatMap(j=>j.locations.map(l=>l.state))).length} states & DC</span><span>Sources & uncertainty included</span><button class="inline-link" data-view="methodology">Explore the evidence ↗</button></div><section class="role-learning"><div class="section-heading"><div><p class="eyebrow">FIRST, FORGET THE ACRONYMS</p><h2>Which of these sounds like you?</h2></div><p>You can explore more than one direction.</p></div><div class="role-choice-grid">${roles.map(r=>`<button class="role-choice" data-start-role="${r.name}"><span class="role-symbol">${r.icon}</span><h3>${r.verb}</h3><p>${r.description}</p><span class="role-foot">${r.title} <b>↗</b></span></button>`).join('')}</div></section><div class="beginner-note"><span>↳</span><p><strong>Not sure? That’s a valid starting point.</strong> You can leave interests open. We’ll show the differences and let you change your mind.</p></div>`;}
function wizard(){const names=['Your background','What interests you','What you’ve tried','Your preferences'];let content='';
 if(step===0)content=`<p class="step-kicker">01 / YOUR BACKGROUND</p><h2>Let’s start where you are.</h2><p class="step-intro">Use the degree you expect to hold when you start work. Exact requirements stay visible on each role.</p><div class="journey-fields">${field('degree','Expected degree',[['','Not sure / skip'],['Bachelor','Bachelor’s'],['Master','Master’s'],['PhD','PhD']])}${field('graduation','Graduation year',[['','Not sure / skip'],...[2025,2026,2027,2028,2029].map(y=>[String(y),String(y)])],'Year is approximate; employer month-by-month windows still need checking.')}${field('industryYears','Full-time industry experience',[[0,'None yet'],[1,'1 year'],[2,'2 years'],[3,'3+ years']],'Leave coursework and academic research out of this count.')}${field('researchYears','Academic research experience',[[0,'None yet'],[1,'1 year'],[2,'2 years'],[3,'3 years'],[4,'4+ years']],'Separate from industry experience. Quality and topic still matter.')}</div><div class="gentle-note">No name, contact details, résumé, or precise location needed.</div>`;
 if(step===1)content=`<p class="step-kicker">02 / WHAT INTERESTS YOU</p><h2>What would you enjoy working on?</h2><p class="step-intro">Pick any that appeal to you. These guide the order of recommendations; they don’t lock you into a career.</p><div class="interest-grid">${roles.map(r=>`<button class="interest-card ${profile.interests.includes(r.name)?'selected':''}" data-pick="interests" data-value="${r.name}" aria-pressed="${profile.interests.includes(r.name)}"><span class="role-symbol">${r.icon}</span><div><strong>${r.verb}</strong><p>${r.description}</p><small>${r.title}</small></div><span>${profile.interests.includes(r.name)?'✓':'+'}</span></button>`).join('')}</div><p class="field-hint">Nothing selected = keep every direction open.</p>`;
 if(step===2)content=`<p class="step-kicker">03 / WHAT YOU’VE TRIED</p><h2>What have you used in a project?</h2><p class="step-intro">Coursework, personal projects, and research all count here. This means exposure, not proof of professional proficiency.</p>${chips('skills',SKILL_OPTIONS.map(x=>typeof x==='string'?x:x.name))}<div class="gentle-note">Still learning? It’s fine to select nothing. We’ll help you identify a useful next project.</div>`;
 if(step===3)content=`<p class="step-kicker">04 / YOUR PREFERENCES</p><h2>Make room for what matters to you.</h2><p class="step-intro">These influence the order of options. You’ll still be able to see roles outside your preferences.</p><div class="journey-fields">${field('workplace','Preferred work arrangement',[['','Open to any arrangement'],['Remote','Remote'],['Hybrid','Hybrid'],['On-site','On-site']])}${field('priority','What should come first?',[['learning','My interests and skills'],['research','Research-oriented work'],['salary','Higher disclosed salary ranges']],'Salary ranges are advertised, not promised offers.')}</div><label class="journey-field"><span>US states you’d consider</span><select data-add-state aria-label="Add a preferred US state"><option value="">Choose a state to add…</option>${states.map(s=>`<option>${s}</option>`).join('')}</select></label>${profile.states.length?chips('states',profile.states):'<p class="field-hint">No states selected = anywhere in the US.</p>'}<label class="check-row generous"><input type="checkbox" data-profile="relocate" ${profile.relocate?'checked':''}>I’m also open to other US locations</label><label class="check-row generous"><input type="checkbox" data-remember ${remember?'checked':''}>Remember these preferences on this device</label><p class="field-hint">No profile information is sent to a server or included in shared links. Clear it whenever you like.</p>`;
 return `<div class="wizard-wrap"><aside class="wizard-sidebar"><p class="eyebrow">BUILD YOUR COMPASS</p><h2>A little context.<br>A better starting point.</h2><ol>${names.map((n,i)=>`<li class="${i===step?'current':i<step?'done':''}"><button data-step="${i}" ${i>step?'disabled':''}><span>${i<step?'✓':i+1}</span>${n}</button></li>`).join('')}</ol><button class="text-button" data-view="explore">Skip to the job explorer →</button></aside><section class="wizard-card" aria-live="polite">${content}<div class="wizard-actions"><button class="button" data-journey="back">← ${step?'Back':'Home'}</button><span>${step+1} of 4</span><button class="button primary" data-journey="next">${step===3?'Show my starting point ↗':'Continue →'}</button></div></section></div>`;
}
function matchCard(item){const j=item.job;const prefConcerns=(item.preferenceReasons||[]).filter(x=>/^(No preferred|Salary is not|Disclosed salary ranges are below|Work arrangement is not)/.test(x));const reasons=unique([...(item.matched||[]),...(item.preferenceReasons||[]).filter(x=>!prefConcerns.includes(x))]).slice(0,2);const concerns=unique([...(item.gaps||[]),...(item.unknown||[]),...prefConcerns]).slice(0,2);return `<article class="personal-card"><div class="personal-card-top"><span class="match-status ${item.status}"><span></span>${statusNames[item.status]}</span><button class="save-button ${context.saved.includes(j.id)?'saved':''}" data-save="${escape(j.id)}" aria-label="${context.saved.includes(j.id)?'Unsave':'Save'} ${escape(j.company+' '+j.title)}" aria-pressed="${context.saved.includes(j.id)}">${context.saved.includes(j.id)?'▣':'▢'}</button></div><p class="company-line">${escape(j.company)}</p><h3><button class="card-title" data-detail="${escape(j.id)}">${escape(j.title)}</button></h3><p class="personal-meta">${escape(locationText(j))}<br>${escape(salaryText(j))}</p><div class="tags">${tag(sourceNames[j.newgradStatus]||'Eligibility unclear')}${j.reviewLevel==='automated-discovery'?tag('Automated discovery','amber'):''}${tag(j.roleFamily,'blue')}</div><div class="match-explanation">${reasons.length?`<strong>Why it’s on your radar</strong>${reasons.map(t=>`<p class="reason">✓ ${escape(t)}</p>`).join('')}`:''}${concerns.length?`<strong>${item.status==='gap'?'What differs':'Before you apply'}</strong>${concerns.map(t=>`<p class="concern">↳ ${escape(t)}</p>`).join('')}`:''}${item.skillMatches?.length?`<p class="skill-match">Your project exposure: ${escape(item.skillMatches.join(', '))}</p>`:''}</div><div class="personal-card-actions"><button class="details-link" data-detail="${escape(j.id)}">Read the requirements ↗</button><label class="compare-checkbox"><input type="checkbox" data-compare="${escape(j.id)}" ${context.compare.includes(j.id)?'checked':''}>Compare</label></div></article>`;}
function careerMap(ranked){const max=Math.max(1,...ROLE_FAMILIES.map(r=>ranked.filter(x=>x.job.roleFamily===r).length));return `<section class="compass-panel"><div class="section-heading compact"><div><p class="eyebrow">YOUR OPPORTUNITY MAP</p><h3>Different paths, different requirements.</h3></div><span class="chart-unit">Unique postings</span></div><div class="map-legend"><span class="aligned">● Basics align</span><span class="confirm">● Check details</span><span class="gap">● Condition differs</span></div>${ROLE_FAMILIES.map(r=>{const group=ranked.filter(x=>x.job.roleFamily===r);return `<button class="career-map-row" data-focus-role="${r}" aria-label="Explore ${r}, ${group.length} postings"><span>${r}</span><span class="stacked-track">${['aligned','confirm','gap'].map(s=>{const n=group.filter(x=>x.status===s).length;return `<span class="${s}" style="width:${100*n/max}%" title="${n} ${statusNames[s]}"></span>`;}).join('')}</span><b>${group.length}</b></button>`;}).join('')}<p class="field-hint">Click a direction to prioritize it. Counts use this profile and the selected evidence scope. Alignment covers recorded basics only.</p></section>`;}
function scenario(ranked){const relevant=ranked.filter(x=>x.status!=='gap'&&(!profile.interests.length||profile.interests.includes(x.job.roleFamily)));const candidates=SKILL_OPTIONS.map(x=>typeof x==='string'?x:x.name).filter(s=>!profile.skills.includes(s));if(!candidates.includes(scenarioSkill))scenarioSkill=candidates[0]||'';const next=normalizeProfile({...profile,skills:scenarioSkill?[...profile.skills,scenarioSkill]:profile.skills,relocate:scenarioWide||profile.relocate});const changed=rankJobs(pool(),next);const before=relevant.reduce((n,x)=>n+(x.skillMentionsMatched||[]).length,0);const after=changed.filter(x=>x.status!=='gap'&&(!profile.interests.length||profile.interests.includes(x.job.roleFamily))).reduce((n,x)=>n+(x.skillMentionsMatched||[]).length,0);const regionCount=p=>relevant.filter(x=>p.relocate||!p.states.length||x.job.remote&&x.job.remoteScope==='nationwide'||x.job.locations.some(l=>p.states.includes(l.state))).length;
 return `<section class="compass-panel experiment-panel"><div class="section-heading compact"><div><p class="eyebrow">TRY A DIFFERENT PATH</p><h3>What if I changed one thing?</h3></div><span class="experiment-symbol">↗</span></div><label class="journey-field"><span>Imagine adding project exposure in</span><select data-scenario-skill ${candidates.length?'':'disabled'}>${candidates.map(s=>`<option ${scenarioSkill===s?'selected':''}>${escape(s)}</option>`).join('')}</select></label><div class="scenario-stat" aria-live="polite"><span><small>Current skill connections</small><strong>${before}</strong></span><b>→</b><span><small>With ${escape(scenarioSkill||'your skills')}</small><strong>${after}</strong></span></div><p class="field-hint">Across ${relevant.length} roles without a recorded basic conflict in your interests, count one connection for each selected skill mentioned in a posting. A posting may contribute several connections. This measures exposure overlap, not eligibility.</p><label class="check-row generous"><input type="checkbox" data-scenario-wide ${scenarioWide?'checked':''}>Also explore every US location</label><p class="field-hint">Location preferences cover <strong>${regionCount(profile)} → ${regionCount(next)}</strong> of those ${relevant.length} roles. Remote work only counts across all states when nationwide eligibility is explicit; other roles use their stated states.</p><button class="button" data-journey="apply-scenario" ${scenarioSkill||scenarioWide?'':'disabled'}>Use this scenario in my profile</button><button class="inline-link" data-journey="reset-scenario">Reset experiment</button></section>`;
}
function learning(ranked){const relevant=ranked.filter(x=>x.status!=='gap'&&(!profile.interests.length||profile.interests.includes(x.job.roleFamily)));const counts=new Map();for(const x of relevant)for(const s of unique(x.skillGaps||[]))counts.set(s,(counts.get(s)||0)+1);const top=[...counts].sort((a,b)=>b[1]-a[1])[0];const role=roles.find(r=>profile.interests.includes(r.name))||roles.find(r=>r.name===ranked.find(x=>x.status!=='gap')?.job.roleFamily)||roles[1];return `<section class="next-steps"><div class="section-heading"><div><p class="eyebrow">MAKE EXPLORATION USEFUL</p><h2>Three next steps you can actually take.</h2></div><button class="button" data-journey="export-plan">↓ Save my plan</button></div><div class="next-step-grid"><article><span>01 / READ TO COMPARE</span><h3>Read two roles, not twenty titles.</h3><p>Pick two postings from different employers. Compare the degree and experience pathways, then save the one you want to investigate.</p><p class="step-evidence">${unique(relevant.map(x=>x.job.company)).length} employers in your interest set have a role without a recorded basic conflict.</p></article><article><span>02 / MAKE SOMETHING SMALL</span><h3>${top?`Explore ${escape(top[0])} with a project.`:'Try a small project in your direction.'}</h3><p>${escape(role.project)}</p><p class="step-evidence">${top?`${escape(top[0])} appears as a recorded required-skill gap in ${top[1]} of ${relevant.length} relevant postings. Check alternatives in the source.`:'Project ideas illustrate the work; completing one does not establish job readiness.'}</p></article><article><span>03 / RESOLVE ONE UNKNOWN</span><h3>Turn uncertainty into a question.</h3><p>Check the original posting for a graduation window, expected experience, and work location. If the source is unclear, keep that question on your shortlist.</p><p class="step-evidence">${relevant.filter(x=>x.status==='confirm').length} relevant postings still need requirements confirmed for this profile.</p></article></div></section>`;}
function results(){const ranked=rankJobs(pool(),profile),n=s=>ranked.filter(x=>x.status===s).length;const selected=ranked.filter(x=>(tab==='all'?x.status!=='gap':x.status===tab)&&(allDirections||!profile.interests.length||profile.interests.includes(x.job.roleFamily)));const chipsText=[profile.degree?`${profile.degree}’s`.replace('PhD’s','PhD'):'Degree open',profile.graduation?`Class of ${profile.graduation}`:'Graduation open',...profile.interests,profile.relocate||!profile.states.length?'US-wide':profile.states.join(', ')];return `<section class="results-hero"><div><p class="eyebrow">YOUR COMPASS / A STARTING POINT, NOT A VERDICT</p><h1>Let’s find your way in.</h1><p>Follow your interests. See the evidence. Change your mind.</p><div class="tags">${chipsText.map(s=>tag(s)).join('')}</div></div><div class="results-hero-actions"><button class="button" data-journey="edit">Edit my preferences ↗</button><button class="text-button" data-journey="clear">Clear my profile</button></div></section><div class="match-count-grid">${[['aligned','Stated basics align','Still check the full job description.'],['confirm','Worth checking','Some requirements or skills need confirmation.'],['gap','A condition differs','See what differs; your interests can still evolve.']].map(([s,title,note])=>`<button class="match-count ${s} ${tab===s?'active':''}" data-match-tab="${s}"><span>${title}</span><strong>${n(s)}</strong><small>${note}</small></button>`).join('')}</div><div class="scope-note"><label>Search scope <select data-scope aria-label="Personalized search scope"><option value="graduate" ${scope==='graduate'?'selected':''}>Explicit graduate / zero-experience</option><option value="early" ${scope==='early'?'selected':''}>Also include 0–2 year pathways</option><option value="all" ${scope==='all'?'selected':''}>Also investigate unclear eligibility</option></select></label><p>${ranked.length} postings considered. Preferences reorder roles; stated basic conflicts are shown separately. No hiring probability is calculated.</p></div><div class="compass-grid">${careerMap(ranked)}${scenario(ranked)}</div><section id="personal-options"><div class="section-heading"><div><p class="eyebrow">YOUR EXPLORATION SHORTLIST</p><h2>${tab==='all'?'Start a little closer to your interests.':statusNames[tab]}</h2></div><span class="muted">${selected.length} postings</span></div>${profile.interests.length?`<label class="check-row generous"><input type="checkbox" data-all-directions ${allDirections?"checked":""}>Also show directions I haven’t selected</label><p class="field-hint">${allDirections?"Showing every role family.":`Focusing on ${escape(profile.interests.join(" and "))}.`} The opportunity map above always shows all five directions.</p>`:""}<div class="match-tabs" role="group" aria-label="Filter personalized recommendations">${[['all','Explore options'],['aligned','Basics align'],['confirm','Check details'],['gap','See differences']].map(([v,t])=>`<button data-match-tab="${v}" class="${v===tab?'active':''}" aria-pressed="${v===tab}">${t}</button>`).join('')}</div>${selected.length?`<div class="personal-grid">${selected.slice(0,limit).map(matchCard).join('')}</div>${selected.length>limit?`<button class="button load-more" data-journey="more">Show 6 more roles ↓</button>`:''}`:`<div class="empty-state"><h3>No postings in this group yet.</h3><p>This is a sample, not a judgment about your potential. Adjust your background or widen the evidence scope to investigate more options.</p><button class="button" data-journey="edit">Edit preferences</button></div>`}</section>${learning(ranked)}<section class="role-learning"><div class="section-heading"><div><p class="eyebrow">THE ROLES, DECODED</p><h2>What would I actually do?</h2></div></div><div class="role-guide-list">${roles.map(r=>`<details><summary><span>${r.icon}</span>${r.title}<b>+</b></summary><p>${r.day}</p><p><strong>A project to explore the work:</strong> ${r.project}</p><button class="inline-link" data-focus-role="${r.name}">Prioritize this direction ↗</button></details>`).join('')}</div></section>`;}
function draw(focus=false){if(!container)return;container.innerHTML=stage==='welcome'?welcome():stage==='wizard'?wizard():results();if(focus){const h=container.querySelector('.wizard-card h2')||container.querySelector('h1,h2');h?.setAttribute('tabindex','-1');h?.focus({preventScroll:true});container.scrollIntoView({behavior:'smooth',block:'start'});}}
function savePlan(){const ranked=rankJobs(pool(),profile).filter(x=>x.status!=='gap'&&(allDirections||!profile.interests.length||profile.interests.includes(x.job.roleFamily))).slice(0,6);const text=['# My AI career exploration plan',`Snapshot: ${context.meta.snapshotDate}`,`Degree: ${profile.degree||'Not set'}. Graduation: ${profile.graduation||'Not set'}.`,`Interests: ${profile.interests.join(', ')||'Open'}.`,`Project exposure: ${profile.skills.join(', ')||'Not set'}.`,'','## Roles to investigate',...ranked.map(x=>`- ${x.job.company} — ${x.job.title}\n  ${statusNames[x.status]}.\n  Check: ${[...x.gaps,...x.unknown].join(' ')}\n  Source: ${x.job.url}`),'','## Next steps','1. Compare two official postings from different employers.','2. Build a small project relevant to a skill requested in your shortlist.','3. Resolve one unknown about experience, graduation timing, or location.','','This is a browser-generated exploration aid, not proof of eligibility or hiring probability.'].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='my-ai-career-plan.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function renderJourney(element,ctx){container=element;context=ctx;draw();if(element.dataset.journeyBound)return;element.dataset.journeyBound='true';element.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;let changed=true,focus=false;
 if(b.dataset.pick){const k=b.dataset.pick,v=b.dataset.value;profile[k]=profile[k].includes(v)?profile[k].filter(x=>x!==v):[...profile[k],v];}
 else if(b.dataset.startRole){profile.interests=[b.dataset.startRole];stage='wizard';step=0;focus=true;}
 else if(b.dataset.step!==undefined){step=Number(b.dataset.step);focus=true;}
 else if(b.dataset.matchTab){tab=b.dataset.matchTab;limit=6;}
 else if(b.dataset.focusRole){profile.interests=[b.dataset.focusRole];tab='all';limit=6;context.toast(`Prioritizing ${b.dataset.focusRole}. Other directions remain available.`);}
 else {switch(b.dataset.journey){case 'start':stage='wizard';step=0;focus=true;break;case 'next':if(step<3)step++;else{stage='results';profile=normalizeProfile(profile);}focus=true;break;case 'back':if(step)step--;else stage='welcome';focus=true;break;case 'edit':stage='wizard';step=0;focus=true;break;case 'clear':profile=defaultProfile();remember=false;stage='welcome';scenarioSkill='';scenarioWide=false;focus=true;context.toast('Your profile has been cleared from this browser. Saved jobs are separate.');break;case 'more':limit+=6;break;case 'apply-scenario':if(scenarioSkill)profile.skills=unique([...profile.skills,scenarioSkill]);if(scenarioWide)profile.relocate=true;scenarioWide=false;scenarioSkill='';context.toast('Scenario applied. Edit your preferences to change it back.');break;case 'reset-scenario':scenarioSkill='';scenarioWide=false;break;case 'export-plan':savePlan();changed=false;break;default:changed=false;}}
 if(changed){persist();draw(focus);}
 });element.addEventListener('change',ev=>{const el=ev.target;let changed=true;if(el.dataset.profile){profile[el.dataset.profile]=el.type==='checkbox'?el.checked:el.value;profile=normalizeProfile(profile);}else if(el.hasAttribute('data-remember'))remember=el.checked;else if(el.hasAttribute('data-add-state')){if(el.value)profile.states=unique([...profile.states,el.value]);}else if(el.hasAttribute('data-all-directions')){allDirections=el.checked;limit=6;}else if(el.hasAttribute('data-scope')){scope=el.value;limit=6;}else if(el.hasAttribute('data-scenario-skill'))scenarioSkill=el.value;else if(el.hasAttribute('data-scenario-wide'))scenarioWide=el.checked;else changed=false;if(changed){persist();draw();}});}
